USE book_tours;






SELECT id, cover_image, name, 1 FROM tours;


SELECT id, DATE_ADD(CURDATE(), INTERVAL 7 DAY), DATE_ADD(DATE_ADD(CURDATE(), INTERVAL 7 DAY), INTERVAL (duration_days - 1) DAY), 18 FROM tours;
SELECT id, DATE_ADD(CURDATE(), INTERVAL 21 DAY), DATE_ADD(DATE_ADD(CURDATE(), INTERVAL 21 DAY), INTERVAL (duration_days - 1) DAY), 12 FROM tours;
SELECT id, DATE_ADD(CURDATE(), INTERVAL 35 DAY), DATE_ADD(DATE_ADD(CURDATE(), INTERVAL 35 DAY), INTERVAL (duration_days - 1) DAY), 8 FROM tours;

SELECT id, 1, CONCAT('Khởi hành – ', route), 'Tập trung, làm thủ tục khởi hành. Đoàn đến điểm tham quan đầu tiên, nhận phòng và dùng bữa tối đặc sản.', 'Trưa, Tối' FROM tours;
SELECT t.id, days.day_number, CONCAT('Khám phá điểm đến – ngày ', days.day_number),
  'Dùng bữa sáng, bắt đầu hành trình tham quan các địa danh nổi bật. Hướng dẫn viên chia sẻ câu chuyện văn hóa, sau đó đoàn tự do trải nghiệm ẩm thực địa phương.',
  'Sáng, Trưa, Tối'
FROM tours t
JOIN (
  SELECT 2 AS day_number UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL
  SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL
  SELECT 9 UNION ALL SELECT 10
) days ON days.day_number < t.duration_days;
SELECT id, duration_days, 'Tạm biệt và trở về', 'Ăn sáng, trả phòng. Đoàn tham quan điểm cuối, mua đặc sản và khởi hành về điểm đón ban đầu. Kết thúc hành trình.', 'Sáng, Trưa'
FROM tours WHERE duration_days >= 2;
