INSERT INTO banners (title, subtitle, image_url, cta_text, cta_url, display_order) VALUES
('Chạm vào mùa hè rực rỡ', 'Ưu đãi đến 25% cho hành trình biển đảo trong tháng này', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=2000&q=85', 'Săn ưu đãi', '/tours?type=nghi-duong', 1),
('Việt Nam — Đi để yêu hơn', 'Khám phá những miền đất đẹp nhất trên dải chữ S', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=2000&q=85', 'Khám phá ngay', '/tours?region=domestic', 2),
('Mùa lá đỏ Nhật Bản', 'Hành trình Tokyo — Fuji — Kyoto — Osaka đáng nhớ', 'https://images.unsplash.com/photo-1528360983277-13d401cdc186?auto=format&fit=crop&w=2000&q=85', 'Xem hành trình', '/tours/nhat-ban-cung-duong-vang', 3);
INSERT INTO tours
(destination_id, departure_id, tour_type_id, code, slug, name, summary, description, route, region, duration_days, duration_nights, price, original_price, cover_image, rating, review_count, highlights, included, excluded, policy, is_hot, featured_order)
VALUES
(1, 1, 2, 'BT-DN01', 'da-nang-hoi-an-ba-na', 'Đà Nẵng – Hội An – Bà Nà Hills', 'Hành trình di sản miền Trung với phố cổ, biển xanh và Cầu Vàng.', 'Khám phá vẻ đẹp giao hòa giữa thiên nhiên, văn hóa và nhịp sống hiện đại của miền Trung.', 'TP.HCM – Đà Nẵng – Hội An – Bà Nà', 'domestic', 4, 3, 7690000, 8490000, 'https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=1200&q=85', 4.9, 126, JSON_ARRAY('Check-in Cầu Vàng', 'Dạo phố cổ Hội An', 'Thưởng thức đặc sản miền Trung'), JSON_ARRAY('Vé máy bay khứ hồi', 'Khách sạn 4 sao', 'Ăn uống theo chương trình', 'Hướng dẫn viên'), JSON_ARRAY('Chi phí cá nhân', 'VAT', 'Tiền tip'), JSON_ARRAY('Đặt cọc 50% khi đăng ký', 'Hủy trước 15 ngày hoàn 70%', 'Lịch trình có thể thay đổi phù hợp thực tế'), TRUE, 1),
(2, 1, 1, 'BT-PQ02', 'phu-quoc-thien-duong-bien', 'Phú Quốc – Thiên đường biển xanh', 'Nghỉ dưỡng resort, lặn ngắm san hô và ngắm hoàng hôn Địa Trung Hải.', 'Một kỳ nghỉ trọn vẹn giữa biển xanh, cát trắng và những trải nghiệm giải trí hàng đầu đảo ngọc.', 'TP.HCM – Phú Quốc – Nam Đảo', 'domestic', 3, 2, 5990000, 6690000, 'https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1200&q=85', 4.8, 98, JSON_ARRAY('Cáp treo Hòn Thơm', 'Lặn ngắm san hô', 'Sunset Town'), JSON_ARRAY('Vé máy bay', 'Resort 4 sao', 'Xe tham quan', 'Bữa sáng'), JSON_ARRAY('Vé vui chơi tự chọn', 'Chi phí cá nhân'), JSON_ARRAY('Đặt cọc 50%', 'Không hoàn vé máy bay sau khi xuất'), TRUE, 2),
(3, 1, 1, 'BT-DL03', 'da-lat-ngan-hoa', 'Đà Lạt – Thành phố ngàn hoa', 'Săn mây, thưởng thức cà phê và khám phá nét lãng mạn phố núi.', 'Hành trình nhẹ nhàng dành cho những tâm hồn yêu thiên nhiên, kiến trúc và không khí se lạnh.', 'TP.HCM – Đà Lạt – Cầu Đất', 'domestic', 3, 2, 3290000, 3690000, 'https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?auto=format&fit=crop&w=1200&q=85', 4.7, 82, JSON_ARRAY('Săn mây Cầu Đất', 'Đồi chè xanh', 'Quảng trường Lâm Viên'), JSON_ARRAY('Xe giường nằm', 'Khách sạn 3 sao', 'Các bữa theo lịch'), JSON_ARRAY('Đồ uống', 'Chi phí cá nhân'), JSON_ARRAY('Đặt cọc 40%', 'Hủy trước 10 ngày hoàn 60%'), TRUE, 3),
(4, 2, 4, 'BT-HG04', 'ha-giang-cung-duong-da', 'Hà Giang – Cung đường đá nở hoa', 'Chinh phục Mã Pì Lèng, sông Nho Quế và cao nguyên đá.', 'Cung đường hùng vĩ qua miền biên viễn với những trải nghiệm bản địa khó quên.', 'Hà Nội – Quản Bạ – Đồng Văn – Mèo Vạc', 'domestic', 4, 3, 4290000, NULL, 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=85', 4.9, 144, JSON_ARRAY('Đèo Mã Pì Lèng', 'Du thuyền sông Nho Quế', 'Dinh Vua Mèo'), JSON_ARRAY('Xe du lịch', 'Homestay và khách sạn', 'Vé tham quan'), JSON_ARRAY('Đồ uống', 'Tip tài xế'), JSON_ARRAY('Sức khỏe phù hợp hành trình đèo núi', 'Mang giấy tờ tùy thân'), TRUE, 4),
(5, 2, 2, 'BT-HL05', 'ha-long-du-thuyen-5-sao', 'Hạ Long – Kỳ nghỉ du thuyền 5 sao', 'Ngủ đêm trên vịnh, chèo kayak và thưởng ngoạn kỳ quan thế giới.', 'Trải nghiệm dịch vụ cao cấp giữa hàng nghìn đảo đá kỳ vĩ của vịnh Hạ Long.', 'Hà Nội – Vịnh Hạ Long – Hang Sửng Sốt', 'domestic', 2, 1, 4750000, 5200000, 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1200&q=85', 4.8, 76, JSON_ARRAY('Du thuyền 5 sao', 'Chèo kayak', 'Tiệc hoàng hôn'), JSON_ARRAY('Cabin riêng', '4 bữa trên tàu', 'Vé thắng cảnh'), JSON_ARRAY('Đưa đón Hà Nội', 'Đồ uống'), JSON_ARRAY('Có mặt trước giờ tàu chạy 30 phút'), FALSE, 5),
(6, 1, 1, 'BT-NT06', 'nha-trang-vinh-bien', 'Nha Trang – Vịnh biển gọi mời', 'Du ngoạn vịnh, tắm khoáng và tận hưởng nhịp sống biển.', 'Kết hợp vui chơi, nghỉ dưỡng và ẩm thực trong thành phố biển năng động.', 'TP.HCM – Nha Trang – Hòn Tằm', 'domestic', 4, 3, 5490000, NULL, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=85', 4.6, 61, JSON_ARRAY('Cano tham quan vịnh', 'Tắm bùn khoáng', 'Hải sản địa phương'), JSON_ARRAY('Xe du lịch', 'Khách sạn 4 sao', 'Cano và vé đảo'), JSON_ARRAY('Trò chơi biển', 'Chi phí cá nhân'), JSON_ARRAY('Đặt cọc 50%', 'Tuân thủ an toàn đường thủy'), FALSE, 6),
(7, 1, 3, 'BT-TL07', 'thai-lan-bangkok-pattaya', 'Thái Lan – Bangkok – Pattaya', 'Thành phố sôi động, chùa vàng linh thiêng và thiên đường mua sắm.', 'Hành trình quốc tế dễ đi với nhiều trải nghiệm văn hóa, giải trí và ẩm thực đặc sắc.', 'TP.HCM – Bangkok – Pattaya', 'international', 5, 4, 10990000, 11990000, 'https://images.unsplash.com/photo-1508009603885-50cf7c579365?auto=format&fit=crop&w=1200&q=85', 4.8, 203, JSON_ARRAY('Chùa Phật Vàng', 'Đảo Coral', 'IconSiam'), JSON_ARRAY('Vé máy bay', 'Khách sạn 4 sao', 'Bảo hiểm du lịch'), JSON_ARRAY('Hộ chiếu', 'Tip 25 USD', 'Hành lý quá cước'), JSON_ARRAY('Hộ chiếu còn hạn 6 tháng', 'Đặt cọc 60%'), TRUE, 1),
(8, 1, 3, 'BT-JP08', 'nhat-ban-cung-duong-vang', 'Nhật Bản – Cung đường vàng', 'Tokyo, núi Phú Sĩ, Kyoto và Osaka trong mùa đẹp nhất.', 'Chạm vào tinh hoa Nhật Bản qua sự giao thoa giữa truyền thống lâu đời và hiện đại.', 'TP.HCM – Tokyo – Fuji – Kyoto – Osaka', 'international', 6, 5, 35990000, 38990000, 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=85', 4.9, 187, JSON_ARRAY('Núi Phú Sĩ', 'Chùa Thanh Thủy', 'Shinkansen trải nghiệm'), JSON_ARRAY('Vé máy bay', 'Visa đoàn', 'Khách sạn 3-4 sao', 'Bảo hiểm'), JSON_ARRAY('Tip 42 USD', 'Chi phí cá nhân'), JSON_ARRAY('Nộp hồ sơ trước 25 ngày', 'Phí visa không hoàn lại'), TRUE, 2),
(9, 1, 3, 'BT-KR09', 'han-quoc-seoul-nami', 'Hàn Quốc – Seoul – Đảo Nami', 'Cung điện cổ, đảo Nami lãng mạn và Seoul hiện đại.', 'Khám phá làn sóng văn hóa Hàn Quốc giữa cảnh sắc bốn mùa đầy cuốn hút.', 'TP.HCM – Seoul – Nami – Everland', 'international', 5, 4, 21990000, 23490000, 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&w=1200&q=85', 4.7, 113, JSON_ARRAY('Đảo Nami', 'Cung Gyeongbokgung', 'Everland'), JSON_ARRAY('Vé máy bay', 'Visa đoàn', 'Khách sạn 4 sao'), JSON_ARRAY('Tip 35 USD', 'Chi phí cá nhân'), JSON_ARRAY('Nộp hồ sơ trước 20 ngày', 'Đặt cọc 70%'), FALSE, 3),
(10, 2, 2, 'BT-SP10', 'sa-pa-fansipan-ban-cat-cat', 'Sa Pa – Fansipan – Bản Cát Cát', 'Săn mây trên nóc nhà Đông Dương và khám phá bản làng Tây Bắc.', 'Hành trình giữa biển mây, ruộng bậc thang và nét văn hóa đặc sắc của đồng bào vùng cao.', 'Hà Nội – Sa Pa – Fansipan – Cát Cát', 'domestic', 3, 2, 3890000, 4390000, 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=1200&q=85', 4.8, 96, JSON_ARRAY('Cáp treo Fansipan', 'Bản Cát Cát', 'Săn mây Sa Pa'), JSON_ARRAY('Xe limousine', 'Khách sạn 4 sao', 'Vé tham quan', 'Các bữa theo lịch'), JSON_ARRAY('Vé cáp treo', 'Chi phí cá nhân'), JSON_ARRAY('Đặt cọc 40%', 'Mang trang phục giữ ấm'), TRUE, 7),
(11, 3, 3, 'BT-HUE11', 'hue-co-do-di-san', 'Huế – Cố đô và miền di sản', 'Thăm Đại Nội, lăng tẩm và thưởng thức ca Huế trên sông Hương.', 'Trở về không gian kinh kỳ trầm mặc qua kiến trúc cung đình, ẩm thực và nhã nhạc đặc sắc.', 'Đà Nẵng – Huế – Đại Nội – Lăng Khải Định', 'domestic', 4, 3, 5490000, 5990000, 'https://images.unsplash.com/photo-1509030450996-dd1a26dda07a?auto=format&fit=crop&w=1200&q=85', 4.7, 74, JSON_ARRAY('Đại Nội Huế', 'Ca Huế sông Hương', 'Lăng Khải Định'), JSON_ARRAY('Xe du lịch', 'Khách sạn 4 sao', 'Vé di tích'), JSON_ARRAY('Chi phí cá nhân', 'Đồ uống'), JSON_ARRAY('Đặt cọc 50%', 'Lịch tham quan có thể điều chỉnh'), FALSE, 8),
(12, 1, 1, 'BT-QN12', 'quy-nhon-ky-co-eo-gio', 'Quy Nhơn – Kỳ Co – Eo Gió', 'Biển xanh trong vắt, làng chài bình yên và thiên đường Kỳ Co.', 'Kỳ nghỉ miền biển đầy nắng với những bãi tắm đẹp, hải sản tươi ngon và nhịp sống hiền hòa.', 'TP.HCM – Quy Nhơn – Kỳ Co – Eo Gió', 'domestic', 4, 3, 6290000, 6990000, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=85', 4.8, 88, JSON_ARRAY('Cano Kỳ Co', 'Check-in Eo Gió', 'Hải sản làng chài'), JSON_ARRAY('Vé máy bay', 'Khách sạn 4 sao', 'Cano và vé tham quan'), JSON_ARRAY('Trò chơi biển', 'Chi phí cá nhân'), JSON_ARRAY('Đặt cọc 50%', 'Tuân thủ an toàn đường thủy'), TRUE, 9),
(13, 1, 2, 'BT-CD13', 'con-dao-hanh-trinh-linh-thieng', 'Côn Đảo – Hành trình linh thiêng', 'Khám phá thiên nhiên hoang sơ và những dấu ấn lịch sử hào hùng.', 'Một hành trình lắng đọng kết hợp tham quan di tích, viếng nghĩa trang và tận hưởng biển đảo thanh bình.', 'TP.HCM – Côn Đảo – Bãi Đầm Trầu', 'domestic', 3, 2, 7890000, 8490000, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=85', 4.9, 67, JSON_ARRAY('Bãi Đầm Trầu', 'Nghĩa trang Hàng Dương', 'Vườn quốc gia Côn Đảo'), JSON_ARRAY('Vé máy bay', 'Khách sạn 3 sao', 'Xe tham quan'), JSON_ARRAY('Lễ viếng cá nhân', 'Chi phí ngoài chương trình'), JSON_ARRAY('Trang phục lịch sự tại điểm tâm linh', 'Đặt cọc 60%'), FALSE, 10),
(14, 1, 2, 'BT-SG14', 'singapore-sac-mau-dao-quoc', 'Singapore – Sắc màu đảo quốc', 'Gardens by the Bay, Sentosa và nhịp sống hiện đại Marina Bay.', 'Khám phá đảo quốc xanh sạch với kiến trúc tương lai, khu vui chơi sôi động và văn hóa đa sắc.', 'TP.HCM – Singapore – Sentosa', 'international', 4, 3, 15990000, 17490000, 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1200&q=85', 4.8, 132, JSON_ARRAY('Gardens by the Bay', 'Đảo Sentosa', 'Marina Bay Sands'), JSON_ARRAY('Vé máy bay', 'Khách sạn 4 sao', 'Bảo hiểm du lịch'), JSON_ARRAY('Hộ chiếu', 'Tip 20 USD', 'Chi phí cá nhân'), JSON_ARRAY('Hộ chiếu còn hạn 6 tháng', 'Đặt cọc 60%'), TRUE, 4),
(15, 1, 1, 'BT-BL15', 'bali-thien-duong-nhiet-doi', 'Bali – Thiên đường nhiệt đới', 'Đền thiêng, ruộng bậc thang và những bãi biển đẹp nhất Indonesia.', 'Kỳ nghỉ đậm chất nhiệt đới giữa thiên nhiên xanh mát, văn hóa bản địa và những khoảnh khắc hoàng hôn.', 'TP.HCM – Bali – Ubud – Nusa Dua', 'international', 5, 4, 18990000, 20490000, 'https://images.unsplash.com/photo-1533669955142-6a73332af4db?auto=format&fit=crop&w=1200&q=85', 4.9, 105, JSON_ARRAY('Cổng trời Handara', 'Đền Tanah Lot', 'Ruộng bậc thang Ubud'), JSON_ARRAY('Vé máy bay', 'Resort 4 sao', 'Bảo hiểm'), JSON_ARRAY('Tip 30 USD', 'Hoạt động tự chọn'), JSON_ARRAY('Hộ chiếu còn hạn 6 tháng', 'Đặt cọc 60%'), TRUE, 5),
(16, 1, 3, 'BT-TW16', 'dai-loan-dai-bac-dai-trung', 'Đài Loan – Đài Bắc – Đài Trung', 'Phố cổ Thập Phần, hồ Nhật Nguyệt và tòa tháp Taipei 101.', 'Hành trình giao hòa giữa phố thị sôi động, cảnh sắc hồ núi và nét văn hóa Á Đông gần gũi.', 'TP.HCM – Đài Bắc – Đài Trung – Nam Đầu', 'international', 5, 4, 20990000, 22490000, 'https://images.unsplash.com/photo-1470004914212-05527e49370b?auto=format&fit=crop&w=1200&q=85', 4.7, 91, JSON_ARRAY('Thả đèn trời Thập Phần', 'Hồ Nhật Nguyệt', 'Taipei 101'), JSON_ARRAY('Vé máy bay', 'Visa đoàn', 'Khách sạn 4 sao'), JSON_ARRAY('Tip 35 USD', 'Chi phí cá nhân'), JSON_ARRAY('Nộp hồ sơ trước 20 ngày', 'Đặt cọc 70%'), FALSE, 6),
(17, 1, 1, 'BT-DB17', 'dubai-ky-quan-sa-mac', 'Dubai – Kỳ quan giữa sa mạc', 'Burj Khalifa, safari sa mạc và thành phố xa hoa bậc nhất.', 'Trải nghiệm kiến trúc kỷ lục, dịch vụ đẳng cấp và cuộc phiêu lưu trên những đồi cát vàng.', 'TP.HCM – Dubai – Abu Dhabi', 'international', 5, 4, 26990000, 28990000, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=85', 4.8, 79, JSON_ARRAY('Burj Khalifa', 'Desert Safari', 'Đại thánh đường Sheikh Zayed'), JSON_ARRAY('Vé máy bay', 'Visa Dubai', 'Khách sạn 4 sao'), JSON_ARRAY('Tip 40 USD', 'Vé lên đỉnh Burj Khalifa'), JSON_ARRAY('Nộp hồ sơ trước 20 ngày', 'Đặt cọc 70%'), TRUE, 7),
(18, 1, 3, 'BT-EU18', 'chau-au-phap-thuy-si-y', 'Châu Âu – Pháp – Thụy Sĩ – Ý', 'Paris hoa lệ, Alps hùng vĩ và những thành phố nghệ thuật nước Ý.', 'Hành trình kinh điển qua những biểu tượng văn hóa, kiến trúc và cảnh quan đẹp nhất châu Âu.', 'TP.HCM – Paris – Lucerne – Milan – Rome', 'international', 8, 7, 58990000, 62990000, 'https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=1200&q=85', 4.9, 156, JSON_ARRAY('Tháp Eiffel', 'Núi Titlis', 'Đấu trường Colosseum'), JSON_ARRAY('Vé máy bay', 'Visa Schengen', 'Khách sạn 4 sao', 'Bảo hiểm'), JSON_ARRAY('Tip 64 EUR', 'Chi phí cá nhân'), JSON_ARRAY('Nộp hồ sơ trước 45 ngày', 'Đặt cọc 50%'), TRUE, 8);
